/* screens.c - drawing whole screens from the converted art.
 *
 * The art is generated by tools/convert.py (see build/art.h) and lives in
 * the switchable banks, so each function switches to the right bank before
 * reading it. Background tiles go in the first pattern table ($0000),
 * sprite tiles in the second ($1000); PPU_CTRL tells the chip which is which. */

#include "art.h"
#include "mmc1.h"
#include "ppu.h"
#include "screens.h"
#include "text.h"

/* The sprite list (OAM, "object attribute memory"): 64 sprites x 4 bytes, at
 * $0200 in RAM. The vblank handler copies it to the graphics chip every frame.
 * Each sprite: Y position minus 1, tile number, attributes (bits 0-1:
 * palette), X position. */
#define OAM ((unsigned char *)0x0200)

/* Move every sprite below the bottom of the screen, which hides it. */
static void hide_sprites(void) {
    unsigned char i = 0;
    do {
        OAM[i] = 0xFF;
        i += 4;
    } while (i != 0);    /* i wraps from 252 back to 0 after the 64th sprite */
}

void show_overworld(unsigned char player) {
    const Sprite *p;
    unsigned char i;

    mmc1_set_bank(TERRAIN_BANK);
    ppu_set_addr(PPU_TILES);
    ppu_write(terrain.tiles, terrain.tile_count * 16u);
    ppu_set_addr(PPU_PALETTES);
    ppu_write(terrain.palettes, 16);

    /* The player's tiles, palettes, and the tile and palette of each of its
     * 16 sprites. Their positions are set separately, by place_player(). */
    mmc1_set_bank(players_bank[player]);
    p = players[player];
    ppu_set_addr(PPU_SPRITE_TILES);
    ppu_write(p->tiles, p->tile_count * 16u);
    ppu_set_addr(PPU_SPRITE_PALETTES);
    ppu_write(p->palettes, 16);

    hide_sprites();
    for (i = 0; i < 16; ++i) {
        OAM[(i << 2) + 1] = p->tile_map[i];
        OAM[(i << 2) + 2] = p->sprite_palettes[i];
    }
}

void place_player(unsigned char x, unsigned char y) {
    unsigned char row, col, i = 0;
    for (row = 0; row < 32; row += 8) {
        for (col = 0; col < 32; col += 8) {
            OAM[i]     = y + row - 1;       /* the chip draws sprites a line late */
            OAM[i + 3] = x + col;
            i += 4;
        }
    }
}

/* Draw a text box with its corners at tiles (left, top) and (right, bottom),
 * on the first nametable. If `open`, the bottom edge is left off, for a box
 * that runs off the bottom of the screen. Its inside is the font's space,
 * which is all the box's fill color. */
static void draw_box(unsigned char left, unsigned char top,
                     unsigned char right, unsigned char bottom, unsigned char open) {
    unsigned char x, y, first, middle, last;
    for (y = top; y <= bottom; ++y) {
        if (y == top) {
            first = BOX_TILE + 0; middle = BOX_TILE + 1; last = BOX_TILE + 2;
        } else if (y == bottom && !open) {
            first = BOX_TILE + 5; middle = BOX_TILE + 6; last = BOX_TILE + 7;
        } else {
            first = BOX_TILE + 3; middle = FONT_TILE;    last = BOX_TILE + 4;
        }
        ppu_set_addr(PPU_NAMETABLE0 + y * 32u + left);
        PPU_DATA = first;
        for (x = left + 1; x < right; ++x) {
            PPU_DATA = middle;
        }
        PPU_DATA = last;
    }
}

void show_battle(unsigned char enemy) {
    const Battle *b;
    const unsigned char *map;
    unsigned char y;

    hide_sprites();

    /* The backdrop fills the whole screen... */
    mmc1_set_bank(BACKDROP_BANK);
    ppu_set_addr(PPU_TILES);
    ppu_write(backdrop.tiles, backdrop.tile_count * 16u);
    ppu_set_addr(PPU_NAMETABLE0);
    ppu_write(backdrop.nametable, 960);

    /* ...then the enemy's tiles go in after the backdrop's, and its 16x16-tile
     * area is written over the backdrop, one row of 16 tiles at a time. */
    mmc1_set_bank(battles_bank[enemy]);
    b = battles[enemy];
    ppu_set_addr(PPU_TILES + BACKDROP_TILES * 16u);
    ppu_write(b->tiles, b->tile_count * 16u);

    map = b->tile_map;
    for (y = 0; y < 16; ++y) {
        ppu_set_addr(PPU_NAMETABLE0 + (BATTLE_ENEMY_Y + y) * 32u + BATTLE_ENEMY_X);
        ppu_write(map, 16);
        map += 16;
    }

    ppu_set_addr(PPU_ATTRIBUTES);
    ppu_write(b->attributes, 64);
    ppu_set_addr(PPU_PALETTES);
    ppu_write(b->palettes, 16);

    /* The text boxes: the log across the top, the menu strip at the bottom,
     * in the backdrop's colors (see convert.py). */
    mmc1_set_bank(BOX_BANK);
    ppu_set_addr(PPU_TILES + BOX_TILE * 16u);
    ppu_write(box.tiles, box.count * 16u);
    text_load(BOX_INK, BOX_FILL);
    draw_box(0, LOG_Y - 1, 31, LOG_Y + LOG_LINES, 0);
    draw_box(0, MENU_Y - 1, 31, 29, 1);
}

void show_story(const char *text) {
    static const unsigned char colors[4] = BOX_COLORS;
    const char *t;
    unsigned char lines, length, y;

    hide_sprites();

    /* Only the box tiles and the font, in the backdrop's palette. */
    mmc1_set_bank(BOX_BANK);
    ppu_set_addr(PPU_TILES + BOX_TILE * 16u);
    ppu_write(box.tiles, box.count * 16u);
    text_load(BOX_INK, BOX_FILL);
    ppu_set_addr(PPU_PALETTES);
    ppu_write(colors, 4);

    /* Fill the screen with the font's space, which is all the fill color,
     * then (straight after, in memory) set every area to palette 0. */
    ppu_set_addr(PPU_NAMETABLE0);
    ppu_fill(FONT_TILE, 960);
    ppu_fill(0, 64);
    draw_box(0, STORY_TOP - 2, 31, STORY_PROMPT + 2, 0);

    /* Count the lines, to center them, double-spaced, between STORY_TOP and
     * STORY_BOTTOM. (The longest story, STORY_SIZE, is about 9 lines.) */
    lines = 0;
    for (t = text; *t; ++lines) {
        t += text_wrap(t, STORY_WIDTH);
        while (*t == ' ') {
            ++t;
        }
    }
    y = STORY_TOP + (STORY_BOTTOM - STORY_TOP + 2 - lines * 2) / 2;
    for (t = text; *t; y += 2) {
        length = text_wrap(t, STORY_WIDTH);
        text_write(STORY_X, y, t, length);
        t += length;
        while (*t == ' ') {
            ++t;
        }
    }
    text_print(12, STORY_PROMPT, "PRESS A");
}
